      "unit": "km",
      "source": "North Sea Environmental Protection Agency (NSEPA)",
      "related_domains": ["environmental", "spatial"]
    },
    {
      "type": "Technical",
      "requirement": "All substations must comply with IEC 61400-3 standards for offshore wind turbine design.",
