  "regulatory_entities": [
    {
      "entity_name": "North Sea Environmental Protection Agency (NSEPA)",
      "jurisdiction": "Regional (North Sea coastal states)",
      "role": "Environmental regulation and enforcement"
    },
    {
      "entity_name": "International Electrotechnical Commission (IEC)",
      "jurisdiction": "International",
      "role": "Standard-setting for electrical systems"
